# -*- coding: utf-8 -*-
"""Handle trades endpoints for MT4 (replaces OANDA)."""

from .apirequest import APIRequest
from .decorators import dyndoc_insert, endpoint
from .responses.trades import responses
from abc import abstractmethod
import os
import sys

# Add parent directory to path for imports
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))


class Trades(APIRequest):
    """Trades - abstract baseclass to handle the trades endpoints for MT4."""

    ENDPOINT = ""
    METHOD = "GET"

    @abstractmethod
    @dyndoc_insert(responses)
    def __init__(self, accountID, tradeID=None):
        """Instantiate a Trades APIRequest instance.

        Parameters
        ----------
        accountID : string
            the account_id of the account (MT4 account number).

        tradeID : string
            ID of the trade (MT4 ticket number)

        """
        endpoint = self.ENDPOINT.format(accountID=accountID, tradeID=tradeID)
        super(Trades, self).__init__(endpoint, method=self.METHOD)


@endpoint("mt4/v1/accounts/{accountID}/trades")
class TradesList(Trades):
    """Get a list of trades for an MT4 Account."""

    @dyndoc_insert(responses)
    def __init__(self, accountID, params=None):
        """Instantiate a TradesList request.

        Parameters
        ----------
        accountID : string (required)
            id of the MT4 account to perform the request on.

        params : dict (optional)
            query params to send (filter by symbol, etc.)

        Example::

            >>> from mt4_endpoints.trades import TradesList
            >>> client = MT4Client()
            >>> r = TradesList(accountID="123456")
            >>> result = client.request(r)
            >>> print(result)

        Output::
            {
                "trades": [
                    {
                        "ticket": 12345,
                        "symbol": "EURUSD",
                        "direction": "BUY",
                        "volume": 0.1,
                        "open_price": 1.0950,
                        "current_price": 1.0980,
                        "profit": 30.0
                    }
                ]
            }

        """
        super(TradesList, self).__init__(accountID)
        self.params = params


