@endpoint("mt4/v1/accounts/{accountID}/trades/{tradeID}/close", "PUT")
class TradeClose(Trades):
    """TradeClose - Close a specific open Trade in an MT4 Account."""

    HEADERS = {"Content-Type": "application/json"}

    @dyndoc_insert(responses)
    def __init__(self, accountID, tradeID, data=None):
        """Instantiate a TradeClose request.

        Parameters
        ----------
        accountID : string (required)
            id of the MT4 account to perform the request on.

        tradeID : string (required)
            id of the trade to close (MT4 ticket number).

        data : dict (optional)
            data to send (volume to close partially).

        Data body example::
            {
                "volume": 0.05
            }

        Example::

            >>> from mt4_endpoints.trades import TradeClose
            >>> client = MT4Client()
            >>> data = {"volume": 0.05}
            >>> r = TradeClose(accountID="123456", tradeID=12345, data=data)
            >>> result = client.request(r)
            >>> print(result)

        Output::
            {
                "ticket": 12345,
                "close_price": 1.0980,
                "profit": 15.0
            }

        """
        super(TradeClose, self).__init__(accountID, tradeID)
        self.data = data


@endpoint("mt4/v1/accounts/{accountID}/trades/{tradeID}/modify", "PUT")
class TradeModify(Trades):
    """TradeModify - Modify stop loss and take profit for an MT4 trade."""

    HEADERS = {"Content-Type": "application/json"}

    @dyndoc_insert(responses)
    def __init__(self, accountID, tradeID, data=None):
        """Instantiate a TradeModify request.

        Parameters
        ----------
        accountID : string (required)
            id of the MT4 account to perform the request on.

        tradeID : string (required)
            id of the trade to modify.

        data : dict (required)
            data with stop_loss and/or take_profit.

        Data body example::
            {
                "stop_loss": 1.0900,
                "take_profit": 1.1050
            }

        Example::

            >>> from mt4_endpoints.trades import TradeModify
            >>> client = MT4Client()
            >>> data = {"stop_loss": 1.0900, "take_profit": 1.1050}
            >>> r = TradeModify(accountID="123456", tradeID=12345, data=data)
            >>> result = client.request(r)
            >>> print(result)

        Output::
            {
                "ticket": 12345,
                "stop_loss": 1.0900,
                "take_profit": 1.1050,
                "success": true
            }

        """
        super(TradeModify, self).__init__(accountID, tradeID)
        self.data = data


