# ============ MT4 Trade Helper Class ============

class MT4Trade:
    """Helper class for MT4 trade operations (replaces OANDA trade objects)."""
    
    def __init__(self, ticket, symbol, direction, volume, open_price,
                 current_price, profit, stop_loss=0, take_profit=0, comment=""):
        """
        Initialize an MT4 trade object.
        
        Parameters:
        -----------
        ticket : int
            MT4 ticket number
        symbol : str
            Instrument symbol (e.g., 'EURUSD')
        direction : str
            'BUY' or 'SELL'
        volume : float
            Trade volume in lots
        open_price : float
            Opening price
        current_price : float
            Current market price
        profit : float
            Current profit/loss
        stop_loss : float
            Stop loss price (0 if none)
        take_profit : float
            Take profit price (0 if none)
        comment : str
            Trade comment
        """
        self.ticket = ticket
        self.symbol = symbol
        self.direction = direction
        self.volume = volume
        self.open_price = open_price
        self.current_price = current_price
        self.profit = profit
        self.stop_loss = stop_loss
        self.take_profit = take_profit
        self.comment = comment
    
    def to_dict(self):
        """Convert to dictionary for API response."""
        return {
            'ticket': self.ticket,
            'symbol': self.symbol,
            'direction': self.direction,
            'volume': self.volume,
            'open_price': self.open_price,
            'current_price': self.current_price,
            'profit': self.profit,
            'stop_loss': self.stop_loss,
            'take_profit': self.take_profit,
            'comment': self.comment
        }


